# frozen_string_literal: true

require_relative '../../spec_helper'
require 'fileutils'
require 'tmpdir'
require 'cli/commands/build_command'
require 'core/generated_marker'

# rjui-usecolormode-template-lacks-generated-sentinel: the hook is copied into
# the generated hooks tree, so `jui lint-generated` checks it like any other
# generated file. The template must carry the same markers, and ownership must
# be decided by that one marker rather than a second, divergent string.
RSpec.describe 'useColorMode hook template' do
  let(:template_path) do
    File.expand_path('../../../lib/react/templates/use_color_mode.ts', __dir__)
  end
  let(:template) { File.read(template_path) }

  # Mirrors jui_tools lint-generated: sentinel in the head, footer in the tail.
  HEAD_SCAN_LINES = 30
  TAIL_SCAN_LINES = 5

  it 'carries the @generated sentinel where lint-generated scans for it' do
    head = template.lines.first(HEAD_SCAN_LINES).join
    expect(head).to include(RjuiTools::Core::GeneratedMarker::SENTINEL)
    expect(head).to include('AUTO-GENERATED FILE — DO NOT EDIT')
  end

  it 'carries the END footer where lint-generated scans for it' do
    tail = template.lines.last(TAIL_SCAN_LINES).join
    expect(tail).to include(RjuiTools::Core::GeneratedMarker::END_LINE)
  end

  it 'keeps generated TS exempt from consumer eslint configs' do
    expect(template).to include('/* eslint-disable */')
  end

  describe 'refresh contract' do
    let(:instance) { described_class = RjuiTools::CLI::Commands::BuildCommand.allocate }

    def run_in(dir, existing: nil)
      Dir.chdir(dir) do
        instance.instance_variable_set(:@config, { 'hooks_directory' => 'hooks' })
        FileUtils.mkdir_p('hooks')
        File.write('hooks/useColorMode.ts', existing) if existing
        instance.send(:ensure_use_color_mode_hook)
        File.read('hooks/useColorMode.ts')
      end
    end

    it 'creates the hook when absent' do
      Dir.mktmpdir do |dir|
        expect(run_in(dir)).to eq(template)
      end
    end

    it 'refreshes a copy carrying the sentinel' do
      Dir.mktmpdir do |dir|
        stale = template.sub('useSyncExternalStore(subscribe', 'useSyncExternalStore( subscribe')
        expect(run_in(dir, existing: stale)).to eq(template)
      end
    end

    # Copies shipped before the banner existed are still library-owned; they
    # must migrate once instead of being mistaken for user customizations.
    it 'refreshes a pre-banner copy identified by its JSDoc line' do
      Dir.mktmpdir do |dir|
        legacy = "\"use client\";\n/**\n * Generated by rjui build — do not edit by hand.\n */\n"
        expect(run_in(dir, existing: legacy)).to eq(template)
      end
    end

    it 'leaves a user-customized copy alone' do
      Dir.mktmpdir do |dir|
        mine = "\"use client\";\nexport const useColorMode = () => 'light';\n"
        expect(run_in(dir, existing: mine)).to eq(mine)
      end
    end
  end
end
